import{_ as s,o as n,c as i,ah as a}from"./chunks/framework.ChH6X6u6.js";const m=JSON.parse('{"title":"Réinscriptions","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/admin/reinscriptions.md","filePath":"src/guide/admin/reinscriptions.md"}'),r={name:"guide/admin/reinscriptions.md"};function l(t,e,o,c,u,d){return n(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="reinscriptions" tabindex="-1">Réinscriptions <a class="header-anchor" href="#reinscriptions" aria-label="Permalink to &quot;Réinscriptions&quot;">​</a></h1><p>Une fois les <a href="/era-guide/guide/admin/decisions-fin-annee.html">décisions de fin d&#39;année</a> prises, réinscrivez les élèves dans l&#39;année suivante, classe par classe : les admis dans une classe du niveau suivant, les redoublants dans une classe du même niveau. ERA crée pour chacun une <strong>nouvelle inscription</strong> dans la nouvelle année ; son inscription de l&#39;année écoulée, avec ses notes, bulletins et paiements, reste intacte.</p><h2 id="avant-de-commencer" tabindex="-1">Avant de commencer <a class="header-anchor" href="#avant-de-commencer" aria-label="Permalink to &quot;Avant de commencer&quot;">​</a></h2><ol><li><strong>Créez et préparez l&#39;année suivante</strong> : ses classes et ses grilles de frais (voir <a href="/era-guide/guide/admin/structure-etablissement.html#preparer-l-annee-suivante">Préparer l&#39;année suivante</a>). Ajoutez les classes qui n&#39;existaient pas encore, par exemple les Terminales C et D si la 1ère D monte en Terminale.</li><li><strong>Vérifiez les niveaux</strong> : chaque classe de l&#39;année écoulée et de la nouvelle année doit avoir son niveau (voir <a href="/era-guide/guide/admin/structure-etablissement.html#niveaux">Niveaux</a>).</li><li><strong>Prenez les décisions</strong> de fin d&#39;année : un élève sans décision n&#39;est pas réinscrit.</li></ol><h2 id="reinscrire-une-classe" tabindex="-1">Réinscrire une classe <a class="header-anchor" href="#reinscrire-une-classe" aria-label="Permalink to &quot;Réinscrire une classe&quot;">​</a></h2><ol><li>Ouvrez <strong>Élèves et admissions → Réinscriptions</strong>.</li><li>Choisissez <strong>Depuis</strong> (l&#39;année écoulée), <strong>Vers</strong> (la nouvelle année) et la <strong>Classe</strong>. La liste des classes indique combien d&#39;élèves restent à placer.</li><li>Les élèves sont répartis selon leur décision : <ul><li><strong>Admis en …</strong> : choisissez leur classe dans la nouvelle année, parmi les classes du niveau suivant sur le même site ;</li><li><strong>Redoublent en …</strong> : choisissez leur classe parmi les classes du même niveau.</li></ul></li><li>Cliquez sur <strong>Réinscrire n élèves en …</strong>.</li></ol><p>Quand il n&#39;y a qu&#39;une classe possible, elle est déjà choisie. Quand il y en a plusieurs (Terminale C et Terminale D), ERA choisit celle de la même <strong>série</strong> que la classe d&#39;origine s&#39;il y en a une ; sinon, choisissez.</p><p>Ne sont pas réinscrits :</p><ul><li>les élèves qui <strong>quittent l&#39;établissement</strong>, et les admis du dernier niveau de l&#39;établissement ;</li><li>les élèves <strong>sans décision</strong> : un lien <strong>Décider maintenant</strong> mène aux décisions de leur classe ;</li><li>les élèves <strong>déjà inscrits</strong> dans la nouvelle année, par exemple placés à la main : ils ne sont jamais déplacés. Vous pouvez donc relancer la réinscription sans risque.</li></ul><h2 id="ce-qui-suit-l-eleve" tabindex="-1">Ce qui suit l&#39;élève <a class="header-anchor" href="#ce-qui-suit-l-eleve" aria-label="Permalink to &quot;Ce qui suit l&#39;élève&quot;">​</a></h2><ul><li>Ses <strong>matières de spécialité</strong> sont reprises dans sa nouvelle inscription si la classe d&#39;arrivée les propose toujours au choix. Son coefficient personnel est gardé dans le même département ; dans un autre département, c&#39;est le coefficient de ce département qui s&#39;applique.</li><li>Ses <strong>frais optionnels</strong> (cantine, transport…) ne sont pas repris : la famille les choisit de nouveau chaque année. La caisse voit ceux de l&#39;an dernier et peut les reprendre en un clic, voir <a href="/era-guide/guide/caissier/inscriptions-et-paiements.html#definir-les-frais-dus">Inscriptions et paiements</a>.</li></ul><h2 id="impayes" tabindex="-1">Impayés <a class="header-anchor" href="#impayes" aria-label="Permalink to &quot;Impayés&quot;">​</a></h2><p>Chaque élève qui doit encore de l&#39;argent sur l&#39;année écoulée est marqué <strong>Impayé</strong> avec le montant restant. La réinscription n&#39;est <strong>pas bloquée</strong> : le solde est à régulariser à la caisse.</p><h2 id="effectif" tabindex="-1">Effectif <a class="header-anchor" href="#effectif" aria-label="Permalink to &quot;Effectif&quot;">​</a></h2><p>Si une classe choisie dépasserait son effectif maximum, cochez <strong>Dépasser l&#39;effectif maximum</strong> (la case nomme la classe concernée) pour réinscrire quand même.</p><h2 id="ensuite" tabindex="-1">Ensuite <a class="header-anchor" href="#ensuite" aria-label="Permalink to &quot;Ensuite&quot;">​</a></h2><ul><li>Un élève mal placé se déplace avec un <a href="/era-guide/guide/secretariat/changements-de-classe.html">changement de classe</a> dans la nouvelle année ; un élève qui change de site passe par un <a href="/era-guide/guide/secretariat/transferts-sites.html">transfert de site</a>.</li><li>La décision d&#39;un élève réinscrit ne peut plus être modifiée ni annulée : la page des décisions affiche « Réinscrit en … ».</li><li>Au moment de la rentrée, basculez l&#39;année en cours avec <strong>Définir comme actuelle</strong> dans <strong>Paramétrage scolaire → Années scolaires</strong>.</li></ul><div class="tip custom-block"><p class="custom-block-title">Les nouveaux élèves</p><p>Les nouveaux élèves arrivent par les <a href="/era-guide/guide/secretariat/candidatures.html">candidatures</a> : un dossier validé en juin peut déjà être placé dans une classe de l&#39;année suivante.</p></div>',18)])])}const g=s(r,[["render",l]]);export{m as __pageData,g as default};
